mapper.select:
SELECT *
FROM sys_depart
WHERE id IN (
    SELECT dep_id
    FROM sys_user_depart
    WHERE user_id = (
        SELECT id
        FROM sys_user
        WHERE username = #{username}
    )
)

    AND org_category = #{category}

SELECT * FROM sys_depart
WHERE
del_flag = '0'

    AND tenant_id = #{tenantId}



        AND parent_id = #{parentId}



            AND (parent_id is null or parent_id='')





    AND depart_name LIKE #{bindName}

ORDER BY depart_order DESC

SELECT id,depart_name,org_code,parent_id FROM sys_depart 
where
depart_name = #{departName}

    and tenant_id = #{tenantId}


    and parent_id = #{parentId}

order by create_time desc

SELECT sd.depart_name, sud.user_id, sd.id as deptId, sd.parent_id FROM sys_depart sd RIGHT JOIN sys_user_depart sud on sd.id = sud.dep_id and sd.del_flag = 0 WHERE sud.user_id IN
#{item.id}
AND sd.tenant_id = #{tenantId} order by sd.org_code

SELECT id,depart_name,org_code,parent_id FROM sys_depart
where
depart_name = #{departName}
and tenant_id = #{tenantId}


        and parent_id = #{parentId}


        and (parent_id is null or parent_id = '')


and del_flag = 0
ORDER BY create_time DESC

select username from sys_user where id in (select user_id from sys_user_depart where dep_id in

    #{item}

)

SELECT id,depart_name,parent_id,depart_name_en,depart_name_abbr,depart_order,description,org_category,org_code,mobile,fax,address,memo, position_id FROM sys_depart
WHERE
1=1

    AND tenant_id = #{tenantId}


    AND parent_id = #{parentId}


    AND (parent_id IS NULL OR parent_id='')


    and id in

        #{id}


ORDER BY depart_order DESC

SELECT sd.depart_name, sud.user_id, sd.id as deptId, sd.parent_id, sd.org_category FROM sys_depart sd RIGHT JOIN sys_user_depart sud on sd.id = sud.dep_id and sd.del_flag = 0 WHERE sud.user_id IN
#{item.id}
order by sd.org_code

select sd.depart_name, sd.id, sd.iz_leaf, sd.org_category, sd.parent_id, sd.org_code from sys_depart sd left join sys_position sp on sd.position_id = sp.id
where sd.parent_id = #{parentId}
and sd.org_category = '3' 

    and sp.post_level  <  #{postLevel}


    and sd.id != #{departId}

order by sd.depart_order,sd.create_time desc

SELECT id FROM sys_depart
WHERE parent_id = #{parentId}
and depart_name = #{postName}
and tenant_id = #{tenantId}
and org_category = '3'
and del_flag = 0

select sd.depart_name, sd.id, sd.iz_leaf, sd.org_category, sd.parent_id, sd.org_code from sys_depart sd left join sys_position sp on sd.position_id = sp.id where sd.parent_id in
#{item}
and sd.org_category = '3' order by sd.depart_order,sd.create_time desc
